        assertTrue(matches(CustomerFilter.byName("ada aal"), ADA));
        assertTrue(matches(CustomerFilter.byName("aal ada"), ADA));
        assertFalse(matches(CustomerFilter.byName("ada virtanen"), ADA));
    }

    @Test
    void whitespaceIsNotSignificant() {
        assertTrue(matches(CustomerFilter.byName("   ada \t  aal  "), ADA));
        assertTrue(matches(CustomerFilter.byName("   "), JARNO));
        assertEquals(List.of("ada", "aal"), CustomerFilter.byName("  ada   aal ").terms());
    }

    @Test
    void matchingIgnoresCaseAndAccentsInBothDirections() {
        assertTrue(matches(CustomerFilter.byName("makinen"), JARNO));
