        assertTrue(matches(CustomerFilter.byName("mäkinen"), JARNO));
        assertTrue(matches(CustomerFilter.byName("MÄKINEN"), JARNO));
        assertTrue(matches(CustomerFilter.byName("josephine"), JOSEPHINE));
        assertTrue(matches(CustomerFilter.byName("joséphine"), JOSEPHINE));
    }

    @Test
    void substringsMatch() {
        assertTrue(matches(CustomerFilter.byName("alto"), ADA));
        assertFalse(matches(CustomerFilter.byName("altox"), ADA));
    }

    @Test
    void noStatusSelectedAcceptsEveryStatus() {
        CustomerFilter filter = CustomerFilter.byName("a");
        assertTrue(matches(filter, ADA));
        assertTrue(matches(filter, JARNO));
        assertTrue(matches(filter, JOSEPHINE));
    }

    @Test
    void selectedStatusesAreTheOnlyOnesAccepted() {
        CustomerFilter filter = CustomerFilter.byStatus(CustomerStatus.ACTIVE, CustomerStatus.CLOSED);
        assertTrue(matches(filter, ADA));
        assertFalse(matches(filter, JARNO));
        assertTrue(matches(filter, JOSEPHINE));
    }

    @Test
    void bothPartsHaveToMatch() {
        CustomerFilter filter = new CustomerFilter("aaltonen", Set.of(CustomerStatus.CLOSED));
        assertFalse(matches(filter, ADA), "right name, wrong status");
        assertFalse(matches(filter, JARNO), "wrong name, wrong status");
        assertTrue(matches(filter, JOSEPHINE));
    }

