+package com.example.customers;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.List;
+import java.util.Set;
+
+import com.example.customers.domain.Customer;
+import com.example.customers.domain.CustomerFilter;
+import com.example.customers.domain.CustomerStatus;
+
+import org.junit.jupiter.api.Test;
+
+/** What the backend considers a match. */
+class CustomerFilterTest {
+
+    private static final Customer ADA =
+            new Customer(1, "Ada", "Aaltonen", "ada@example.com", "Finland", CustomerStatus.ACTIVE);
+    private static final Customer JARNO =
+            new Customer(2, "Jarno", "Mäkinen", "jarno@example.com", "Netherlands", CustomerStatus.PENDING);
+    private static final Customer JOSEPHINE =
+            new Customer(3, "Joséphine", "Aaltonen", "jos@example.com", "Portugal", CustomerStatus.CLOSED);
+
+    private static boolean matches(CustomerFilter filter, Customer customer) {
+        return filter.asPredicate().test(customer);
+    }
+
+    @Test
+    void emptyFilterMatchesEverything() {
+        assertTrue(CustomerFilter.EMPTY.isEmpty());
+        for (Customer customer : List.of(ADA, JARNO, JOSEPHINE)) {
+            assertTrue(matches(CustomerFilter.EMPTY, customer));
+        }
+    }
+
+    @Test
+    void everyTermMustMatchEitherName() {
+        assertTrue(matches(CustomerFilter.byName("ada aal"), ADA));
+        assertTrue(matches(CustomerFilter.byName("aal ada"), ADA));
+        assertFalse(matches(CustomerFilter.byName("ada virtanen"), ADA));
+    }
+
+    @Test
+    void whitespaceIsNotSignificant() {
+        assertTrue(matches(CustomerFilter.byName("   ada \t  aal  "), ADA));
+        assertTrue(matches(CustomerFilter.byName("   "), JARNO));
+        assertEquals(List.of("ada", "aal"), CustomerFilter.byName("  ada   aal ").terms());
+    }
+
+    @Test
+    void matchingIgnoresCaseAndAccentsInBothDirections() {
+        assertTrue(matches(CustomerFilter.byName("makinen"), JARNO));
+        assertTrue(matches(CustomerFilter.byName("MAKINEN"), JARNO));
+        assertTrue(matches(CustomerFilter.byName("mäkinen"), JARNO));
+        assertTrue(matches(CustomerFilter.byName("MÄKINEN"), JARNO));
+        assertTrue(matches(CustomerFilter.byName("josephine"), JOSEPHINE));
+        assertTrue(matches(CustomerFilter.byName("joséphine"), JOSEPHINE));
+    }
+
+    @Test
+    void substringsMatch() {
+        assertTrue(matches(CustomerFilter.byName("alto"), ADA));
+        assertFalse(matches(CustomerFilter.byName("altox"), ADA));
+    }
+
+    @Test
+    void noStatusSelectedAcceptsEveryStatus() {
+        CustomerFilter filter = CustomerFilter.byName("a");
+        assertTrue(matches(filter, ADA));
+        assertTrue(matches(filter, JARNO));
+        assertTrue(matches(filter, JOSEPHINE));
+    }
+
+    @Test
+    void selectedStatusesAreTheOnlyOnesAccepted() {
+        CustomerFilter filter = CustomerFilter.byStatus(CustomerStatus.ACTIVE, CustomerStatus.CLOSED);
+        assertTrue(matches(filter, ADA));
+        assertFalse(matches(filter, JARNO));
+        assertTrue(matches(filter, JOSEPHINE));
+    }
+
+    @Test
+    void bothPartsHaveToMatch() {
+        CustomerFilter filter = new CustomerFilter("aaltonen", Set.of(CustomerStatus.CLOSED));
+        assertFalse(matches(filter, ADA), "right name, wrong status");
+        assertFalse(matches(filter, JARNO), "wrong name, wrong status");
+        assertTrue(matches(filter, JOSEPHINE));
+    }
+
+    @Test
+    void filtersWithTheSameMeaningAreEqual() {
+        assertEquals(CustomerFilter.EMPTY, new CustomerFilter(null, null));
+        assertEquals(CustomerFilter.EMPTY, new CustomerFilter("  ", Set.of()));
+        assertEquals(CustomerFilter.byName("vir"), new CustomerFilter(" vir ", null));
+    }
+}
