+            page.click("vaadin-multi-select-combo-box-item >> text=" + status);
+        }
+        page.keyboard().press("Escape");
+    }
+
+    @SuppressWarnings("unchecked")
+    private List<String> selectedStatuses() {
+        return (List<String>) page.evaluate(
+                "document.querySelector('#status-filter').selectedItems.map(item => item.label ?? item)");
+    }
+
+    /** The path and query string currently in the address bar. */
+    private String path() {
+        return (String) page.evaluate("location.pathname + location.search");
+    }
+}
