+package com.example.customers;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertThrows;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.List;
+import java.util.Set;
+
+import com.example.customers.domain.Customer;
+import com.example.customers.domain.CustomerFilter;
+import com.example.customers.domain.CustomerRepository;
+import com.example.customers.domain.CustomerSort;
+import com.example.customers.domain.CustomerStatus;
+import com.example.customers.domain.QueryLog;
+
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+
+/** The backend pages, sorts and filters, and keeps saying so in the query log. */
+class CustomerRepositoryTest {
+
+    private QueryLog queryLog;
+    private CustomerRepository repository;
+
+    @BeforeEach
+    void setUp() {
+        queryLog = new QueryLog();
+        repository = new CustomerRepository(queryLog);
+    }
+
+    @Test
+    void countsOnlyMatchingCustomers() {
+        assertEquals(500, repository.count());
+        assertEquals(15, repository.count(CustomerFilter.byName("vir")));
+        assertEquals(167, repository.count(CustomerFilter.byStatus(CustomerStatus.ACTIVE)));
+        assertEquals(0, repository.count(CustomerFilter.byName("zzz")));
+    }
+
+    @Test
+    void pagingAddressesTheMatchingRows() {
+        CustomerFilter filter = CustomerFilter.byName("a");
+        assertEquals(454, repository.count(filter));
+
+        List<Customer> firstPage = repository.findAll(0, 200, List.of(), filter);
+        List<Customer> secondPage = repository.findAll(200, 200, List.of(), filter);
+        List<Customer> lastPage = repository.findAll(400, 200, List.of(), filter);
+
+        assertEquals(200, firstPage.size());
+        assertEquals(200, secondPage.size());
+        assertEquals(54, lastPage.size());
+        assertTrue(firstPage.stream().allMatch(filter.asPredicate()));
+        assertEquals(454, List.of(firstPage, secondPage, lastPage).stream()
+                .flatMap(List::stream).map(Customer::id).distinct().count());
+    }
+
+    @Test
+    void filteredPagesAreStillCapped() {
+        assertThrows(IllegalArgumentException.class,
+                () -> repository.findAll(0, CustomerRepository.MAX_PAGE_SIZE + 1, List.of(),
+                        CustomerFilter.byName("a")));
+    }
+
+    @Test
+    void sortingAppliesToTheMatchingRows() {
+        CustomerFilter filter = new CustomerFilter("a", Set.of(CustomerStatus.CLOSED));
+        List<Customer> page = repository.findAll(0, 10, List.of(new CustomerSort("lastName", false)), filter);
+
+        assertEquals(10, page.size());
+        assertTrue(page.stream().allMatch(filter.asPredicate()));
+        assertEquals(page.stream().map(Customer::lastName)
+                        .sorted(String.CASE_INSENSITIVE_ORDER.reversed()).toList(),
+                page.stream().map(Customer::lastName).toList());
+    }
+
+    @Test
+    void everyFilteredQueryIsRecordedOnce() {
+        queryLog.clear();
+
+        repository.count(CustomerFilter.byName("vir"));
+        repository.findAll(0, 5, List.of(), CustomerFilter.byName("vir"));
+        repository.count();
+        repository.findAll(0, 5, List.of());
+
+        assertEquals(List.of(15, 500), queryLog.countQueries());
+        assertEquals(List.of(
+                        new QueryLog.PageQuery(0, 5, 5),
+                        new QueryLog.PageQuery(0, 5, 5)),
+                queryLog.pageQueries());
+        assertEquals(10, queryLog.rowsFetched());
+    }
+}
